vec3 tileColor(Tile t, int l, vec2 gx, vec2 gy) {
  vec2 n = vec2(72.0, 36.0) / float(1 << l);
  vec2 k = n * (TC_PX / TC_SZ);
  return textureGrad(uTileC, vec3((1.0 + t.f * TC_PX) / TC_SZ, t.layer), gx * k, gy * k).rgb;
