const float TM_MIP = 0.060;
int marchLevel(float dKm) {
  return clamp(int(floor(log2(max(1.0, TM_MIP * dKm / TH_KM)) + 0.5)), 0, 2);
}
float marchH(vec2 uv, int lmin, float lodG) {
  float acc = 0.0, rem = 1.0;
  for (int l = 0; l < 3; l++) {
    if (l < lmin) continue;
